if($method==='PUT' && ($d['accion']??'')==='estado'){$id=(int)($d['id']??0);$state=clean_string($d['estado']??'');if(!$id||!in_array($state,['activo','inactivo'],true))json_response(['error'=>'Estado inválido.'],422);$st=$pdo->prepare('UPDATE promociones SET estado=?,actualizado_en=NOW() WHERE id=?');$st->execute([$state,$id]);json_response(['ok'=>true,'mensaje'=>'Estado de promoción actualizado.']);}
if($method==='POST'||$method==='PUT'){$id=(int)($d['id']??0);$code=strtoupper(clean_string($d['codigo']??''));$name=clean_string($d['nombre']??'');$desc=clean_string($d['descripcion']??'');$type=clean_string($d['tipo_descuento']??'porcentaje');$value=filter_var($d['valor']??null,FILTER_VALIDATE_FLOAT);$start=clean_string($d['fecha_inicio']??'');$end=clean_string($d['fecha_fin']??'');$status=clean_string($d['estado']??'activo');$max=($d['usos_maximos']??'')===''?null:filter_var($d['usos_maximos'],FILTER_VALIDATE_INT);if(!preg_match('/^[A-Z0-9_-]{3,40}$/',$code)||$name===''||!in_array($type,['porcentaje','monto'],true)||$value===false||$value<=0||($type==='porcentaje'&&$value>100)||($type==='monto'&&$value>10000)||!in_array($status,['activo','inactivo'],true)||!$start||!$end||strtotime($end)<=strtotime($start)||($max!==null&&($max===false||$max<1)))json_response(['error'=>'Revisa código, nombre, descuento, vigencia y límite de usos.'],422);try{if($method==='POST'){$st=$pdo->prepare('INSERT INTO promociones(codigo,nombre,descripcion,tipo_descuento,valor,fecha_inicio,fecha_fin,estado,usos_maximos,creado_por) VALUES(?,?,?,?,?,?,?,?,?,?)');$st->execute([$code,$name,$desc?:null,$type,$value,$start,$end,$status,$max,$user['id']]);}else{if(!$id)json_response(['error'=>'Promoción inválida.'],422);$st=$pdo->prepare('UPDATE promociones SET codigo=?,nombre=?,descripcion=?,tipo_descuento=?,valor=?,fecha_inicio=?,fecha_fin=?,estado=?,usos_maximos=?,actualizado_en=NOW() WHERE id=?');$st->execute([$code,$name,$desc?:null,$type,$value,$start,$end,$status,$max,$id]);if(!$st->rowCount())json_response(['error'=>'Promoción no encontrada o sin cambios.'],404);}json_response(['ok'=>true,'mensaje'=>'Promoción guardada.']);}catch(PDOException $e){if($e->getCode()==='23000')json_response(['error'=>'Ese código promocional ya existe.'],409);throw $e;}}
